# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HOFFMAN VOLTAMETRESİ İLE SUYUN ELEKTROLİZİ VE AKTİFLİK KURALI</text>\n  <rect x="25" y="46" width="320" height="196" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Suyun Elektrolizi (Hoffman Voltametresi)</text>\n  <text x="42" y="96" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Elektrolit:</tspan> H₂SO₄ damlatılmış saf su</text>\n  <text x="42" y="120" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Katot (-):</tspan> 2H⁺ + 2e⁻ → <tspan font-weight="bold" fill="#dc2626">H₂(g)  (Hacim = 2V)</tspan></text>\n  <text x="42" y="144" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Anot (+):</tspan> H₂O → ½<tspan font-weight="bold" fill="#16a34a">O₂(g)</tspan> + 2H⁺ + 2e⁻ <tspan font-weight="bold" fill="#16a34a">(Hacim = V)</tspan></text>\n  <text x="42" y="168" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Net:</tspan> 2H₂O(s) → 2H₂(g) + O₂(g)</text>\n  <rect x="42" y="184" width="286" height="42" rx="6" fill="#eff6ff" stroke="#60a5fa"/>\n  <text x="185" y="209" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Oran: n(H₂) / n(O₂) = V(H₂) / V(O₂) = 2 / 1</text>\n  <rect x="360" y="46" width="315" height="196" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Sulu Çözeltide Öncelik (Yarışma) Kuralı</text>\n  <text x="378" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">KATOTTA (-):</tspan> İndirgenme potansiyeli</text>\n  <text x="388" y="114" font-size="11" fill="#14532d"><tspan font-weight="bold">en büyük (en pasif)</tspan> katyon önce toplanır.</text>\n  <text x="388" y="132" font-size="10" fill="#166534">(Örn: Cu²⁺, Ag⁺, Au³⁺ &gt; H⁺ &gt; Na⁺, Mg²⁺, Al³⁺)</text>\n  <text x="378" y="158" font-size="11" fill="#14532d">• <tspan font-weight="bold">ANOTTA (+):</tspan> Yükseltgenme potansiyeli</text>\n  <text x="388" y="176" font-size="11" fill="#14532d"><tspan font-weight="bold">en büyük (en aktif)</tspan> anyon önce ayrışır.</text>\n  <text x="388" y="194" font-size="10" fill="#166534">(Örn: I⁻ &gt; Br⁻ &gt; Cl⁻ &gt; OH⁻ &gt; SO₄²⁻, NO₃⁻, F⁻)</text>\n  <text x="517" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Aktif metal katyonu varsa katotta H₂ gazı çıkar!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ELEKTROLİZ İLE METAL KAPLAMACILIĞI DÜZENEĞİ (GÜMÜŞ KAPLAMA)</text>\n  <rect x="30" y="48" width="640" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <rect x="60" y="72" width="185" height="145" rx="8" fill="#ffffff" stroke="#b45309" stroke-width="1.5"/>\n  <text x="152" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. ANOT (+) KUTBU</text>\n  <text x="75" y="120" font-size="11" fill="#78350f">• <tspan font-weight="bold">Kaplayacak saf metal</tspan> (Ag)</text>\n  <text x="75" y="142" font-size="11" fill="#78350f">• Yükseltgenerek aşınır:</text>\n  <text x="85" y="162" font-size="11" font-weight="bold" fill="#b45309">Ag(k) → Ag⁺(suda) + e⁻</text>\n  <text x="75" y="186" font-size="11" fill="#78350f">• Kütlesi zamanla azalır.</text>\n  <rect x="262" y="72" width="175" height="145" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="349" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. ELEKTROLİT ÇÖZELTİ</text>\n  <text x="275" y="120" font-size="11" fill="#1e3a8a">• Kaplama metalinin tuzunu</text>\n  <text x="283" y="138" font-size="11" fill="#1e3a8a">içerir (<tspan font-weight="bold">AgNO₃ çözeltisi</tspan>).</text>\n  <text x="275" y="162" font-size="11" fill="#1e3a8a">• Anottan gelen Ag⁺ kadar</text>\n  <text x="283" y="178" font-size="11" fill="#1e3a8a">katotta Ag⁺ indirgenir.</text>\n  <text x="275" y="200" font-size="11" font-weight="bold" fill="#1d4ed8">• [Ag⁺] derişimi değişmez!</text>\n  <rect x="455" y="72" width="190" height="145" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="550" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">3. KATOT (-) KUTBU</text>\n  <text x="470" y="120" font-size="11" fill="#14532d">• <tspan font-weight="bold">Kaplanacak eşya</tspan> (Demir çatal)</text>\n  <text x="470" y="142" font-size="11" fill="#14532d">• İndirgenme yüzeyde olur:</text>\n  <text x="480" y="162" font-size="11" font-weight="bold" fill="#15803d">Ag⁺(suda) + e⁻ → Ag(k)</text>\n  <text x="470" y="186" font-size="11" fill="#14532d">• Eşyanın yüzeyi Ag ile kaplanır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KATODİK KORUMA VE KURBAN ELEKTROT SEÇİM İLKESİ</text>\n  <rect x="25" y="48" width="320" height="192" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">KURBAN ELEKTROT (ANOT)</text>\n  <text x="42" y="98" font-size="11" fill="#7f1d1d">• Korunacak metalden <tspan font-weight="bold">daha aktif</tspan> seçilir.</text>\n  <text x="42" y="120" font-size="11" fill="#7f1d1d">• Yükseltgenme eğilimi: E°_yük(Kurban) &gt; E°_yük(Fe)</text>\n  <text x="42" y="142" font-size="11" fill="#7f1d1d">• Demir (Fe) için: <tspan font-weight="bold">Mg, Al, Zn</tspan> kullanılır.</text>\n  <text x="42" y="164" font-size="11" fill="#7f1d1d">• Zamanla yükseltgenerek aşınır ve tükenir,</text>\n  <text x="50" y="180" font-size="11" fill="#7f1d1d">belirli aralıklarla yenisiyle değiştirilir.</text>\n  <rect x="42" y="192" width="286" height="34" rx="6" fill="#ffffff" stroke="#f87171"/>\n  <text x="185" y="213" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Tepkime: Mg(k) → Mg²⁺ + 2e⁻ (Kendini feda eder)</text>\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">KORUNAN METAL YAPI (KATOT)</text>\n  <text x="378" y="98" font-size="11" fill="#1e3a8a">• Gemi gövdesi, yer altı boru hattı, iskele ayağı</text>\n  <text x="378" y="120" font-size="11" fill="#1e3a8a">• Kurban elektrottan gelen elektronları alır.</text>\n  <text x="378" y="142" font-size="11" fill="#1e3a8a">• Katot konumuna geçtiği için <tspan font-weight="bold">yükseltgenemez</tspan>.</text>\n  <text x="378" y="164" font-size="11" fill="#1e3a8a">• Paslanma (korozyon) tamamen önlenir.</text>\n  <rect x="378" y="192" width="279" height="34" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="517" y="213" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Aktiflik: Mg &gt; Al &gt; Zn &gt; Fe &gt; Ni &gt; Cu &gt; Ag</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
